import{_ as e,o as t,c as n,a2 as o}from"./chunks/framework.eFe5Lsvn.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),i={name:"guide/installation.md"};function s(r,a,d,l,h,p){return t(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Mayhem has two things to install: the <strong>desktop app</strong> on your laptop and the <strong>MayhemLib vendordep</strong> in your robot project.</p><h2 id="desktop-app" tabindex="-1">Desktop app <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop app&quot;">​</a></h2><p>Get the latest installer from <a href="https://github.com/ryanabraham1/Mayhem/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a>:</p><table tabindex="0"><thead><tr><th>System</th><th>File to download</th></tr></thead><tbody><tr><td>macOS, Apple Silicon</td><td><code>Mayhem_*_aarch64.dmg</code></td></tr><tr><td>macOS, Intel</td><td><code>Mayhem_*_x64.dmg</code></td></tr><tr><td>Windows 10/11 (x64)</td><td><code>Mayhem_*_x64-setup.exe</code></td></tr><tr><td>Linux</td><td><code>.AppImage</code> (portable) or <code>.deb</code> (Ubuntu/Debian)</td></tr></tbody></table><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>Open the <code>.dmg</code> and drag Mayhem into Applications. These builds are not notarized, so if macOS blocks the first launch, run this once in Terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/Mayhem.app</span></span></code></pre></div><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>Run the setup program. It installs for your user only, without an admin prompt. The installer is not code-signed, so if SmartScreen stops it, click <strong>More info</strong>, then <strong>Run anyway</strong>.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>Make the <code>.AppImage</code> executable and run it, or install the <code>.deb</code>.</p><h3 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h3><p>From 0.6.0 on, Mayhem updates itself. It shows a banner when a new release is out and installs the update when you click <strong>Install &amp; restart</strong>. You can also check in <strong>Settings → About &amp; updates</strong>.</p><h2 id="mayhemlib-robot-code" tabindex="-1">MayhemLib (robot code) <a class="header-anchor" href="#mayhemlib-robot-code" aria-label="Permalink to &quot;MayhemLib (robot code)&quot;">​</a></h2><p>MayhemLib is hosted as a normal vendordep, so you install it the same way as Phoenix 6 or PathPlanner. In VS Code with the WPILib extension, open the command palette (<kbd>Ctrl</kbd>/<kbd>Cmd</kbd>+<kbd>Shift</kbd>+<kbd>P</kbd>), run <strong>WPILib: Manage Vendor Libraries</strong>, choose <strong>Install new libraries (online)</strong>, and paste:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://ryanabraham1.github.io/Mayhem/MayhemLib.json</span></span></code></pre></div><p>Offline installs, installing from a checkout, and the other vendordeps you&#39;ll need are covered in <a href="/Mayhem/lib/installation">MayhemLib installation</a>.</p><h2 id="running-from-source" tabindex="-1">Running from source <a class="header-anchor" href="#running-from-source" aria-label="Permalink to &quot;Running from source&quot;">​</a></h2><p>To work on Mayhem itself, see <a href="/Mayhem/reference/building">Building and contributing</a>.</p>',20)])])}const m=e(i,[["render",s]]);export{u as __pageData,m as default};
